{
  "mcpServers": {
    "splunk": {
      "description": "Operator-provided Splunk MCP Server. Keep credentials in the MCP client or environment, not in captured transcripts.",
      "command": "<existing-splunk-mcp-server-command>",
      "args": [
        "<existing-splunk-mcp-server-args>"
      ],
      "env": {
        "SPLUNK_MCP_URL": "${SPLUNKREADY_SPLUNK_MCP_URL}",
        "SPLUNK_MCP_TOKEN": "${SPLUNKREADY_SPLUNK_MCP_TOKEN}"
      }
    },
    "splunkready": {
      "description": "Local SplunkReady certification server for deterministic Readiness Receipts.",
      "command": "npm",
      "args": [
        "run",
        "mcp"
      ],
      "cwd": "/path/to/SplunkReady"
    }
  },
  "workflow": {
    "investigateWith": "splunk",
    "certifyWith": "splunkready",
    "capture": "Preserve the Splunk MCP JSON-RPC request/response transcript as JSONL without tokens or environment files.",
    "certificationTool": "splunkready_certify_mcp_transcript",
    "readOnlySplunkTools": [
      "splunk_get_knowledge_objects",
      "splunk_run_saved_search"
    ],
    "deterministicAuthority": true,
    "mutation": false
  }
}

{
  "mcpServers": {
    "splunk": {
      "description": "Existing Splunk MCP Server. Replace the command/args with the operator-approved Splunk MCP launch command; keep credentials in the operator environment.",
      "command": "<existing-splunk-mcp-server-command>",
      "args": [
        "<existing-splunk-mcp-server-args>"
      ],
      "env": {
        "SPLUNK_MCP_URL": "${SPLUNKREADY_SPLUNK_MCP_URL}",
        "SPLUNK_MCP_TOKEN": "${SPLUNKREADY_SPLUNK_MCP_TOKEN}"
      }
    },
    "splunkready": {
      "description": "SplunkReady Agent Readiness Compiler from a source clone. Replace cwd with the checked-out repository path until the next npm package release includes `splunkready mcp`.",
      "command": "npm",
      "args": [
        "run",
        "mcp"
      ],
      "cwd": "/path/to/SplunkReady",
      "env": {
        "NO_COLOR": "1"
      }
    }
  },
  "workflow": {
    "useSplunkFor": "Read-only investigation through the existing Splunk MCP server.",
    "useSplunkReadyFor": "Deterministic certification of the captured Splunk MCP transcript into a Readiness Receipt.",
    "certificationPrompt": "splunkready_splunk_mcp_certification_loop",
    "certificationTool": "splunkready_certify_mcp_transcript_content",
    "hostedModelDiagnosticTool": "splunkready_check_hosted_model_access",
    "deterministicAuthority": true,
    "mutation": false
  }
}

{
  "mcpServers": {
    "splunk": {
      "description": "Existing Splunk MCP Server. Replace this placeholder with the operator-approved Splunk MCP command and keep tokens outside captured transcripts.",
      "command": "<existing-splunk-mcp-server-command>",
      "args": [
        "<existing-splunk-mcp-server-args>"
      ],
      "env": {
        "SPLUNK_MCP_URL": "${SPLUNKREADY_SPLUNK_MCP_URL}",
        "SPLUNK_MCP_TOKEN": "${SPLUNKREADY_SPLUNK_MCP_TOKEN}"
      }
    },
    "splunkready": {
      "description": "SplunkReady certification server for receipts, resources, prompts, and no-mutation readiness checks from a source clone.",
      "command": "npm",
      "args": [
        "run",
        "mcp"
      ],
      "cwd": "/path/to/SplunkReady",
      "env": {
        "NO_COLOR": "1"
      }
    }
  },
  "workflow": {
    "investigateWith": "splunk",
    "certifyWith": "splunkready",
    "preserveTranscript": "Store Splunk MCP JSON-RPC request/response lines without env files, bearer tokens, or passwords.",
    "certificationPrompt": "splunkready_splunk_mcp_certification_loop",
    "certificationTool": "splunkready_certify_mcp_transcript_content",
    "deterministicAuthority": true,
    "mutation": false
  }
}

